-- StudyOS initial migration. Run against a new Supabase project.
create extension if not exists pgcrypto;
create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 display_name text not null default 'Student', timezone text not null default 'UTC', locale text not null default 'en',
 daily_study_capacity_minutes integer not null default 180 check(daily_study_capacity_minutes>0),
 daily_score_threshold integer not null default 70 check(daily_score_threshold between 1 and 100),
 preserve_rest_days boolean not null default true, rest_days integer[] not null default '{5}', review_intervals integer[] not null default '{1,3,7,14}',
 sat_target_date date, sat_target_score integer check(sat_target_score between 400 and 1600), ielts_target_date date, ielts_target_band numeric check(ielts_target_band between 0 and 9),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.profiles enable row level security;
create policy profile_owner on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(btrim(new.raw_user_meta_data->>'full_name'),''),'Student')); return new; end $$;
create trigger new_user_profile after insert on auth.users for each row execute function public.create_profile();

create table public.subjects (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, color text not null default '#7928ef', sort_order integer not null default 0, unique(id,user_id));
alter table public.subjects enable row level security;
create policy owner_access on public.subjects for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create index on public.subjects(user_id);
create trigger touch_updated before update on public.subjects for each row execute function public.touch_updated_at();
