insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('academic-files','academic-files',false,20971520,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy academic_files_read on storage.objects for select to authenticated using(bucket_id='academic-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy academic_files_insert on storage.objects for insert to authenticated with check(bucket_id='academic-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy academic_files_delete on storage.objects for delete to authenticated using(bucket_id='academic-files' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.create_sat_practice(p_title text,p_section text,p_domain uuid,p_difficulty text,p_ids text[]) returns uuid language plpgsql security invoker set search_path=public as $$
declare sid uuid; q text; n integer:=0;
begin
 if cardinality(p_ids)<1 or cardinality(p_ids)>200 then raise exception 'Choose 1–200 questions'; end if;
 insert into sat_sessions(title,section,domain_id,difficulty,planned_question_count) values(p_title,p_section,p_domain,p_difficulty,cardinality(p_ids)) returning id into sid;
 foreach q in array p_ids loop
 insert into sat_session_questions(session_id,row_order,question_identifier) values(sid,n,btrim(q)); n:=n+1;
 end loop;
 return sid;
end $$;
create or replace function public.accept_inbox(p_id uuid,p_title text,p_date date,p_area text,p_subject uuid,p_task boolean,p_event boolean,p_file boolean) returns void language plpgsql security invoker set search_path=public as $$
declare item inbox_items;
begin
 select * into item from inbox_items where id=p_id and user_id=auth.uid() for update;
 if not found then raise exception 'Import not found'; end if;
 if item.status='accepted' then raise exception 'Import already accepted'; end if;
 if p_task then insert into tasks(title,area,subject_id,due_date,source,source_metadata) values(p_title,p_area,p_subject,p_date,'teacher_import',p_id::text); end if;
 if p_event then insert into calendar_events(title,event_date,area,subject_id,event_type) values(p_title,p_date,p_area,p_subject,'school quiz'); end if;
 if p_file and item.file_id is not null then update files set area=p_area,subject_id=p_subject where id=item.file_id; end if;
 update inbox_items set status='accepted',accepted_at=now(),area=p_area,subject_id=p_subject,suggested_date=p_date,suggestion_title=p_title where id=p_id;
end $$;
-- Functions remain invoker-scoped. RLS applies to every write and composite FKs block cross-user links.
revoke execute on function public.create_sat_practice(text,text,uuid,text,text[]) from public;
grant execute on function public.create_sat_practice(text,text,uuid,text,text[]) to authenticated;
revoke execute on function public.accept_inbox(uuid,text,date,text,uuid,boolean,boolean,boolean) from public;
grant execute on function public.accept_inbox(uuid,text,date,text,uuid,boolean,boolean,boolean) to authenticated;
